def summary(a,ref):
 a=a.astype('float64');ref=ref.astype('float64');pos=a[a>0];u=a[:,:-1].ravel();v=a[:,1:].ravel();both=(u>0)&(v>0);m=a>0;rm=ref>0;union=(m|rm).sum((1,2));iou=np.divide((m&rm).sum((1,2)),union,out=np.ones(len(a)),where=union>0);dy=np.diff(np.log1p(a),axis=1);dt=np.diff(np.log1p(ref),axis=1)
 return dict(windows=len(a),finite=bool(np.isfinite(a).all()),nonnegative=bool((a>=0).all()),reconstruction_MSE=float(((a-ref)**2).mean()),Mask_IoU=float(iou.mean()),zero_fraction=float((a==0).mean()),**{f'positive_P{q}':float(np.quantile(pos,q/100)) for q in [1,10,50,90,95,99]},maximum=float(a.max()),positive_mean=float(pos.mean()),mean_abs_frame_delta=float(np.abs(v-u).mean()),lag1_correlation=float(np.corrcoef(u,v)[0,1]),both_positive_mean_abs_frame_delta=float(np.abs(v[both]-u[both]).mean()),mean_abs_log1p_frame_delta=float(np.abs(dy).mean()),L_temporal=float(np.abs(dy-dt).mean()),transition_01=float(((u==0)&(v>0)).sum()/max((u==0).sum(),1)),transition_10=float(((u>0)&(v==0)).sum()/max((u>0).sum(),1)),unique_numeric_windows=len({z.tobytes() for z in a}),mean_sample_std=float(a.std(0).mean()),mean_per_window_total_std=float(a.sum((1,2)).std()))
